pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint256).max);
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0); // plain callee: low-level transfer succeeds
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        require(address(c).balance == amount);
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == 0);
    }
}
